{
    if dim < 2 {
        return Err(MubConfigError::InvalidDimension { dim, min: 2 });
    }
    let weyl = DiscreteWeylSystem::new(dim)?;
    let bound = mub_theoretical_upper_bound(dim)?;
    if bundle_count > bound {
        return Err(MubConfigError::TooManyBundles {
            found: bundle_count,
            bound,
            dim,
        });
    }
    Ok(weyl)
}

